"""Russian report over measured tables, with no automatic promotion to UI."""


def number(value):
    return "—" if value is None else f"{value:.4f}" if isinstance(value, float) else str(value)


def markdown(report, comparison, stability, paired, cases):
    k = max(report["top_k"])
    lines = ["# T20: сравнение учебных моделей", "", f"Снимок: `{report['run_id']}`. Только независимо вымышленные истории.", "",
        "Основным остаётся рейтинг по числу критериев T17. IF и комбинация — эксперименты; граф/M07 не продвигаются в основной рейтинг.",
        "Независимые решения проверяющего не созданы автоматически. T21 и интерфейс ожидаются.", "",
        "## Данные и смысл чисел", "",
        "Training/calibration созданы генератором v2 отдельно от оценки. Holdout использует иное семейство фиксированных историй; метки описывают заложенные тестовые режимы, не свойства людей.",
        "Контрольные деловые/короткие поездки специально похожи на срабатывания правил. Пропуски исключаются из численного сравнения с явным учётом покрытия.",
        "AP/ROC считаются на общей доступной размеченной группе; P@K использует реально выбранное число строк. Основной топ правил не дополняется профилями без срабатываний.",
        "Это сконструированный benchmark. Его метрики не оценивают эффективность на неизвестных реальных случаях; случайность назначения сценариев и доверительные интервалы не заявляются.", "",
        f"## Предписанные опорные опыты (K={k})", "",
        "| Набор | Метод | Доступны / всего | Общая группа | Доля тестовых случаев | AP | ROC AUC | P@K | Диапазон при равных баллах | Выбрано |", "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|"]
    for row in comparison:
        if row["experiment"] in {"baseline", "replicate", "in_domain"} and row["k"] == k:
            lines.append(f"| {row['experiment']} | {row['method']} | {row['available']}/{row['population']} | {row['common_profiles']} | {number(row['positive_prevalence'])} | {number(row['average_precision'])} | {number(row['roc_auc'])} | {number(row['precision_at_k'])} | {number(row['precision_tie_lower'])}–{number(row['precision_tie_upper'])} | {row['selected']} |")
    lines += ["", "Диапазон P@K показывает худший/лучший состав на границе равных баллов; это не доверительный интервал. `in_domain` не размечен: метрики качества для него отсутствуют. Разные seed дают разные profile_id; Jaccard между такими наборами не вычисляется.", "",
              "## Чувствительность на тех же профилях", "",
              "В таблице разделены пересечение опубликованных топов и пересечение после ограничения общей доступной группой. Корреляция использует средние ранги равных баллов, без искусственного порядка по ID.", "",
              "| Опыт | Метод | Общая группа | Вошли / выбыли | Jaccard всего | Jaccard общей группы | Spearman |", "|---|---|---:|---:|---:|---:|---:|"]
    for row in stability:
        if row["comparable"] and row["k"] == k:
            lines.append(f"| {row['experiment']} | {row['method']} | {row['shared_common']} | {row['entered']}/{row['excluded']} | {number(row['end_to_end_jaccard'])} | {number(row['common_population_jaccard'])} | {number(row['spearman_common'])} |")
    paired_index = {(r["experiment"], r["side"], r["method"], r["k"]):r for r in paired}
    lines += ["", "## Отключение групп и граф", "",
              "Для парного сравнения обе стороны ограничены одним пересечением доступных профилей. Разница AP ниже — только разница на этом заранее заданном benchmark; не подбор лучшей модели.", "",
              "| Опыт | Метод | Парная группа | AP базы | AP варианта | Разница AP |", "|---|---|---:|---:|---:|---:|"]
    for row in paired:
        if row["side"] == "variant" and row["k"] == k and (row["experiment"].startswith("without_") or row["experiment"] == "graph"):
            base = paired_index[(row["experiment"], "baseline", row["method"], k)]
            delta = row["average_precision"] - base["average_precision"] if row["average_precision"] is not None and base["average_precision"] is not None else None
            lines.append(f"| {row['experiment']} | {row['method']} | {row['common_profiles']} | {number(base['average_precision'])} | {number(row['average_precision'])} | {number(delta)} |")
    lines += ["", "## Сценарии и ошибки", "",
              "| Сценарий | Метод | Профилей | Доступны | В топе | Тестовые случаи в группе |", "|---|---|---:|---:|---:|---:|"]
    for row in cases:
        lines.append(f"| {row['case_id']} | {row['method']} | {row['profiles']} | {row['available']} | {row['selected']} | {row['positive_labels']} |")
    lines += ["", "Индивидуальные расхождения, численные признаки, объяснения правил и ссылки на сегменты сохранены в `disagreements.parquet`; исходные доказательства — в родителях T19.",
        "Деловые/короткие поездки — отрицательные контроли данного сценарного задания. Срабатывание на них показывает ограничение критерия; оно не является оценкой мотивов человека.", "",
        "## Независимый аудит", "",
        f"Подготовлено {report['audit']['selected']} историй, заполнено 0. Передавайте проверяющему только `review/blind/` и копию `review/ranking_audit.csv`.",
        "`private/audit_key.parquet`, каталог сценариев, оценки и этот отчёт остаются у аналитика до завершения слепого ревью. Стратифицированная выборка не даёт несмещённую точность по всей совокупности.", "",
        "## Решение и ограничения", "",
        "Автоматического выбора модели по holdout нет. Пороги, веса и основной режим не изменены. Рекомендация: сохранить основной режим правил, оставить IF/комбинацию/граф экспериментами и разобрать расхождения с независимым проверяющим.",
        "Граф зависит от размера наблюдаемой группы и предположений условного фона. Константная корреляция и пустые топы отмечены null, а не искусственным 0/1.",
        "Для изменённых окон и цензурированных маршрутов метрики качества выключены: проверяются покрытие и устойчивость. Это не прогноз будущего.",
        "`ui_ready=false`; M07 выключен; приёмка ожидает независимого ревью/T21. Полные параметры, версии, состав наборов, времена и хеши — в JSON и манифестах.", ""]
    return "\n".join(lines)
